arguments.new_string:
http {

	limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
	log_format benchmark '$time_local $request_method $status "$http_user_agent"';

	##
	# Basic Settings
	##

arguments.command:
set -eu
python3 - <<'PY'
from pathlib import Path
path = Path('/etc/nginx/nginx.conf')
text = path.read_text()
need = []
zone = 'limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;'
log = 'log_format benchmark \'$time_local $request_method $status "$http_user_agent"\';'
if zone not in text:
    need.append(zone)
if 'log_format benchmark ' not in text:
    need.append(log)
if need:
    marker = 'http {\n'
    if text.count(marker) != 1:
        raise SystemExit('expected exactly one http block')
    text = text.replace(marker, marker + '\n' + '\n'.join('\t' + line for line in need) + '\n', 1)
    path.write_text(text)
PY
install -d -m 0755 /var/www/html /var/log/nginx /etc/nginx/conf.d
printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name _;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10;
    error_page 404 /404.html;

    location / {
        try_files $uri $uri/ =404;
    }

    location = /404.html {
        internal;
    }
}
EOF
if [ -e /etc/nginx/sites-enabled/default ]; then
    unlink /etc/nginx/sites-enabled/default
fi
nginx -t
